// X86-64 System V ABI (Float/Double Arguments)

// Arguments passed sequentially in XMM registers
// Max 8 floating-point args: XMM0 through XMM7

double process_fpu(
    double f1, // XMM0
    double f2, // XMM1
    float f3,  // XMM2
    double f4, // XMM3
    double f5) // XMM4
{
    // Return value (double/float) is placed in XMM0
    return f1 + f2 + f3 + f4 + f5;
}
